        memo: { q: "Por que um pagamento na Stellar leva um memo?", a: "A Cosmos Pay associa cada pagamento na Stellar ao seu link de pagamento pelo memo do link, um MEMO_ID numérico. A carteira que abre o link SEP-7, com um toque ou pelo QR code, adiciona o memo sozinha. Um pagamento enviado manualmente precisa do mesmo memo: sem ele, a Cosmos Pay não consegue associar o pagamento ao link. Quando a rede confirma um pagamento com o memo certo, cerca de 5 segundos na Stellar, o checkout passa para Pago e o seu webhook é disparado." },
