        match: { q: "Como um pagamento na Solana é associado ao seu link?", a: "Cada link de pagamento da Cosmos Pay na Solana leva uma chave de referência do Solana Pay. A Cosmos Pay encontra na blockchain a transferência que leva essa chave e a associa ao seu link, e o memo do link é registrado com o programa SPL Memo. Quando a rede confirma a transferência, o checkout passa para Pago e a Cosmos Pay dispara os mesmos webhooks que na Stellar, então o mesmo endpoint de webhook serve as duas redes." },
        tokens: { q: "Posso aceitar USDT ou outro token SPL na Solana?", a: "Sim. Na Solana, a Cosmos Pay oferece pelo nome o SOL, a moeda da própria rede, e o USDC, na mainnet e na Devnet. Qualquer outro token SPL, como USDT, é indicado pelo mint ao criar o link. Seu cliente paga no token do link, e esse mesmo token vai direto para o seu endereço Solana assim que a rede confirma o pagamento." },
        testing: { q: "Como testo pagamentos na Solana sem dinheiro real?", a: "Crie uma chave de API de teste (dv_) no dashboard da Cosmos Pay, ou escolha Sandbox ali: os links de pagamento passam a funcionar na Solana Devnet, e o checkout avisa que nenhum fundo real é movimentado. O ativo predefinido da Devnet é o mint de USDC da Devnet da Circle; omita o ativo para cobrar em SOL. Uma chave de produção (prod_) cria os mesmos links na mainnet da Solana: a chave decide a rede, não o código." },
