        deposit: { q: "O que é o endereço de depósito na Monad?", a: "Cada pagamento na Monad com a Cosmos Pay recebe o próprio endereço de depósito, criado só para aquele pagamento, e é esse endereço que o associa ao link. O endereço de depósito só pode repassar o pagamento ao seu endereço Monad, menos a taxa do repasse, que o checkout mostra e a API informa no pagamento como networkFee. A Cosmos Pay não tem nenhuma chave dele." },
        amount: { q: "Por que um link de pagamento na Monad precisa de um valor?", a: "O valor faz parte de como a Cosmos Pay reconhece um pagamento na Monad, enviado a um endereço de depósito criado para ele, então um link de pagamento na Monad precisa de um valor e quem paga não pode escolhê-lo. Um link da Monad também não leva mensagem para a carteira. Para que seus clientes escolham o valor, como em doações, ou para mostrar uma mensagem na carteira deles, como o número do pedido, crie o link na Stellar ou na Solana." },
        tokens: { q: "Em quais tokens posso cobrar na Monad?", a: "Na Monad, a Cosmos Pay oferece pelo nome o MON, a moeda da própria rede, e o USDC na mainnet; qualquer outro token ERC-20 é indicado pelo contrato ao criar o link. A Monad Testnet não tem USDC predefinido, então uma chave de teste (dv_) cobra ali em MON, ou num token que você indicar pelo contrato. Seu cliente paga no token do link, e o endereço de depósito o repassa ao seu endereço Monad, menos a taxa do repasse." },
        fee: { q: "Posso adicionar minha própria taxa a um pagamento na Monad?", a: "Sim. Na Monad, o endereço de depósito que a Cosmos Pay cria para cada pagamento divide o pagamento entre o seu endereço Monad e a carteira de taxas que você escolher. A sua taxa é separada da tarifa do seu plano, que cada pagamento continua pagando. A taxa do repasse é descontada do pagamento, e a API a informa no pagamento como networkFee." },
